const reports = $input.first().json;
const report = Array.isArray(reports) ? reports[0] : reports;
const kpis = report?.kpis_json || {};
const kpiRows = Object.entries(kpis).map(([key, value]) => `<tr><td><strong>${key}</strong></td><td>${typeof value === 'object' ? JSON.stringify(value) : value}</td></tr>`).join('');
const html = report ? `
<h2>Digest rapport agentic Bad Debts</h2>
<p><strong>Resume :</strong></p>
<p>${report.summary || '-'}</p>
<p><strong>Recommandations :</strong></p>
<p>${report.recommendations || '-'}</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial,sans-serif;font-size:13px;">
  <tbody>${kpiRows || '<tr><td colspan="2">Aucun KPI disponible.</td></tr>'}</tbody>
</table>
<p><a href="${$env.PFE_DASHBOARD_URL}/reports">Ouvrir les rapports agentic</a></p>
<p style="color:#666;font-size:12px;">Email interne genere par n8n. La decision reste produite par les regles metier, ML et LangGraph.</p>` : `
<h2>Digest rapport agentic Bad Debts</h2>
<p>Aucun rapport agentic disponible pour le moment.</p>
<p><a href="${$env.PFE_DASHBOARD_URL}/reports">Ouvrir les rapports agentic</a></p>`;
return [{ json: { html_body: html, subject: 'Digest Bad Debts - dernier rapport agentic' } }];
